Translate("ptBR", "prospector-ryedol", {
	title = "Prospector Ryedol",
	subtitle = "Prospector da Liga dos Exploradores",
	found = [=[O acampamento da Liga ao sul do Sítio de Escavação do Pé-de-malho]=],
	hint = [=[Encontre o prospector que sobreviveu à queda da escavação de Hammertoe.]=],
	allegiance = "Liga dos Exploradores",
	aliases = { "Ryedol" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Prospector Ryedol trabalhava sob o explorador Hammertoe Grez em sua escavação no norte dos {link:badlands}Ermos{/link}. Quando o clã Shadowforge atacou, ele foi um dos poucos que escaparam. Agora mantém um pequeno acampamento ao sul do sítio arruinado, com {link:sigrun-ironhew}Sigrun Ironhew{/link} e os outros sobreviventes. É franco e cansado, e diz que todo dia nos Ermos é um dia ruim.]=],
		},
		{
			title = "Importância",
			text = [=[Ryedol é o fio que liga o destino de Hammertoe a {link:ironforge}Altaforja{/link}. Por meio dele o reino soube que os Shadowforge não estavam simplesmente saqueando. Estavam caçando segredos dos titãs, e o conhecimento que Hammertoe levava na cabeça.]=],
		},
		{
			title = "Feitos",
			text = [=[• Escapou do ataque dos Shadowforge à escavação de Hammertoe.
• Soube por um mapa rabiscado que Hammertoe fora levado vivo a {link:uldaman}Uldaman{/link}.
• Enviou um buscador à câmara para encontrar seu antigo mestre.
• Fez chegar o amuleto de Hammertoe ao {link:historian-karnik}Historiador Karnik{/link}, em {link:ironforge}Altaforja{/link}, pela mão de outro.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nada está escrito sobre a vida de Ryedol antes dos {link:badlands}Ermos{/link}.]=],
		},
	},
	chapters = {
		{
			title = "A Picareta da Sorte",
			hint = "Recupere dos Shadowforge a picareta do prospector.",
			text = [=[Ryedol perdeu tudo no ataque, até sua picareta da sorte. Acreditava que um dos Shadowforge a tinha levado. Quando ela voltou para ele, ficou grato. Também ficou inquieto. Os {link:dark-iron-dwarves}Ferro Negro{/link} não haviam atacado a escavação ao acaso, disse ele. Estavam procurando algo.]=],
		},
		{
			title = "Um Sinal de Esperança",
			hint = "Conte ao prospector o que revela o mapa rabiscado a giz.",
			text = [=[Um mapa foi encontrado perto da escavação arruinada, com uma mensagem rabiscada a giz: Hammertoe estava sendo levado a {link:uldaman}Uldaman{/link}. Ryedol o havia chorado como morto. Agora entendia por que os Shadowforge o haviam poupado. Queriam o que Hammertoe sabia das escavações dos titãs. Os {link:dark-iron-dwarves}Ferro Negro{/link} buscavam havia muito modos de construir golens mais fortes. Hammertoe havia estudado os mesmos segredos para detê-los.]=],
		},
		{
			title = "Perspectiva de Fé",
			hint = "Traga ao prospector o que Hammertoe deixou para trás.",
			text = [=[Hammertoe foi encontrado em {link:uldaman}Uldaman{/link}, mas estava morrendo. Mandou de volta seu amuleto, a obra de sua vida, e pediu que ele fosse para Ryedol. Ryedol disse que era mais feliz quando pensava que o mestre já estava morto. Então se recompôs. Hammertoe havia trabalhado com o {link:historian-karnik}Historiador Karnik{/link}, de {link:ironforge}Altaforja{/link}, e Karnik saberia o que o amuleto significava. Ryedol o mandou a ele, para que a morte não fosse em vão.]=],
		},
	},
	mentions = {
		{ text = "Um Anão e Suas Ferramentas" },
		{ text = "Um Sinal de Esperança" },
		{
			text = [=[Um Sinal de Esperança, enviado a {link:uldaman}Uldaman{/link}]=],
		},
		{ text = "Perspectiva de Fé, o amuleto de Hammertoe devolvido" },
		{ text = "Perspectiva de Fé, levado a {link:ironforge}Altaforja{/link}" },
	},
	bonds = {
		{ id = "hammertoe-grez", name = "Hammertoe Grez", note = "seu mestre" },
		{ id = "sigrun-ironhew", name = "Sigrun Ironhew", note = "divide o acampamento com ele" },
		{ id = "historian-karnik", name = "Historiador Karnik", note = "o parceiro de Hammertoe em Altaforja" },
	},
})

