Translate("ptBR", "garek", {
	title = "Garek",
	subtitle = "Agente do Kirin Tor",
	found = "Ravina de Sopravento, a oeste da Ravina Lethlor",
	hint = "Encontre o mago calado que vigia a Ravina Lethlor.",
	allegiance = "Kirin Tor",
	sections = {
		{
			title = "Resumo",
			text = [=[{link:garek-bandarion}Garek{/link} é um mago enviado aos {link:badlands}Ermos{/link} por um mestre do {link:kirin-tor}Kirin Tor{/link}, Krasus. O mago mantém um acampamento solitário perto da {link:lethlor-ravine}Ravina Lethlor{/link} e pouco fala de sua missão, apenas que ela é de grande importância e que diz respeito ao problema que se forma na ravina.]=],
		},
		{
			title = "Importância",
			text = [=[{link:garek-bandarion}Garek{/link} mostra que o {link:kirin-tor}Kirin Tor{/link} ainda vigia a revoada dragônica negra, mesmo nestes anos conturbados. Sob a {link:lethlor-ravine}Ravina Lethlor{/link} jazem dois tenentes de {link:deathwing}Asa da Morte{/link}, e seu mestre decidiu que nenhum risco de libertação deles pode ser permitido.]=],
		},
		{
			title = "Feitos",
			text = [=[• Busca o Sinal da Terra, a chave da prisão dos dracos, roubado por um bando de ogros errantes.
• Aprendeu a história da prisão e de seus construtores {link:dark-iron-dwarves}Ferro Negro{/link}.
• Decidiu que {link:blacklash}Blacklash{/link} e {link:hematus}Hematus{/link} não devem despertar de novo.]=],
		},
		{
			title = "Sem Registro",
			text = [=[{link:garek-bandarion}Garek{/link} não diz quem era antes de entrar a serviço de seu mestre, e nenhum registro o revela.]=],
		},
	},
	chapters = {
		{
			title = "O Sinal da Terra",
			hint = "Recupere a chave roubada para o mago do Kirin Tor.",
			text = [=[O Sinal da Terra foi feito pelos {link:dark-iron-dwarves}Ferro Negro{/link} da {link:angor-fortress}Fortaleza Angor{/link} para prender dois tenentes de {link:deathwing}Asa da Morte{/link}, os dracos gêmeos {link:blacklash}Blacklash{/link} e {link:hematus}Hematus{/link}. Quando ele lhe foi trazido, {link:garek-bandarion}Garek{/link} falou com mais liberdade. Os dragões negros tinham vindo fazer ninho na ravina. Os ogros haviam conseguido roubar o Sinal. A prisão já não era confiável.]=],
		},
		{
			title = "Sonhos Eternos",
			hint = "Acabe com o perigo dos dracos de Lethlor.",
			text = [=[Com o Sinal, as três pedras rúnicas podiam ser retiradas de seus pilares e postas no Selo da Terra. O selo se partiu, e os dracos ficaram livres pelo tempo que levou para matá-los. {link:garek-bandarion}Garek{/link} pediu apenas que seus sonhos se tornassem eternos. Quando isso foi feito, ele se preparou para voltar a Krasus com a notícia de que o {link:kirin-tor}Kirin Tor{/link} não precisava mais temer os prisioneiros de {link:lethlor-ravine}Lethlor{/link}.]=],
		},
	},
	mentions = {
		{ text = "Tremores da Terra, o Sinal recuperado" },
		{ text = "Tremores da Terra, os dracos mortos" },
		{ text = "O Selo da Terra" },
	},
	bonds = {
		{ id = "sigrun-ironhew", name = "Sigrun Ironhew", note = "falou-lhe de quem ajuda" },
		{ id = "blacklash", name = "Blacklash", note = "um prisioneiro de Lethlor" },
		{ id = "hematus", name = "Hematus", note = "um prisioneiro de Lethlor" },
		{ id = "boss-tho-grun", name = "Chefe Tho'grun", note = "roubou o Sinal" },
	},
})

