Translate("ptBR", "lotwil-veriatus", {
	title = "Lotwil Veriatus",
	subtitle = "Mago e Engenhoqueiro de Kharanos",
	found = "Seu acampamento na Terrasseca",
	hint = [=[Encontre o mago gnomo que testa suas invenções na Terrasseca.]=],
	allegiance = "Gnomos · Kharanos",
	aliases = { "Lotwil" },
	sections = {
		{
			title = "Resumo",
			text = [=[Lotwil Veriatus é um {link:gnomes}gnomo{/link} que mistura alquimia, engenharia e magia arcana a serviço de sua própria curiosidade. Veio de {link:kharanos}Kharanos{/link} para os {link:badlands}Ermos{/link} para construir sua maior obra: grilhões de sujeição elemental, que permitiriam a um mago comandar elementais muito mais fortes que qualquer um já invocado. Seu assistente {link:lucien-tosselwrench}Lucien{/link} e seu desajeitado servo mecânico, Servo, dividem seu acampamento. Lotwil é brilhante, distraído e alegremente convencido de que todo contratempo é pequeno.]=],
		},
		{
			title = "Importância",
			text = [=[Lotwil é um estudioso de verdadeira fama nas ciências elementais, e até a {link:horde}Horda{/link} de {link:kargath}Karrath{/link} busca seu parecer. Ele também tem um passado. Há muito tempo, lutou contra um {link:dark-iron-dwarves}Ferro Negro{/link} que distorceu a obra de sua vida em armas, e acreditava esse inimigo morto.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estuda os elementais de rocha dos {link:badlands}Ermos{/link} para construir seus grilhões.
• Resfria e fortalece seus grilhões com óleo gélido e um aparelho chamado girocronátomo.
• Invoca um guardião de pedra com seus grilhões prontos, o que não sai como ele planejou.
• Conhece as marcas do fazedor de golens Argelmach.]=],
		},
		{
			title = "Sem Registro",
			text = [=[As crônicas não contam como Lotwil e Argelmach se conheceram, nem como o {link:dark-iron-dwarves}Ferro Negro{/link} obteve a obra do {link:gnomes}gnomo{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Estudo dos Elementos",
			hint = [=[Reúna o que o gnomo precisa dos elementais de rocha dos Ermos.]=],
			text = [=[Fragmentos dos elementais menores, placas dos maiores e, por fim, as braçadeiras de sujeição rochosa do maior deles. Cada peça permitiu a Lotwil testar seus feitiços contra a substância da rocha viva. Cada teste saiu como ele previa. Ele começou a falar dos elementais que logo controlaria, e de como eles envergonhariam todas as invocações anteriores.]=],
		},
		{
			title = "Isso Vai Ser Difícil",
			hint = [=[Ajude o gnomo a terminar seus grilhões, e lide com o que vier depois.]=],
			text = [=[Os grilhões estavam prontos. Lotwil chamou {link:lucien-tosselwrench}Lucien{/link} e Servo para testemunhar, e invocou um guardião de pedra elemental. Ele não obedeceu. Quando a criatura foi derrotada e seus grilhões recuperados, Lotwil admitiu que aquele não era o resultado que esperava. Não soube dizer o que dera errado. Estava contente, disse, que sua magia estivesse ali para mandar a criatura de volta para casa.]=],
		},
		{
			title = "A Ascensão das Máquinas",
			hint = [=[Leve de Karrath ao acampamento do gnomo o fragmento elemental marcado.]=],
			text = [=[Os fragmentos vinham de golens das {link:burning-steppes}Estepes Ardentes{/link}, e traziam iniciais. Quando Lotwil os viu, seu rosto ficou branco. Ele conhecia as marcas. Pertenciam a Argelmach, um {link:dark-iron-dwarves}Ferro Negro{/link} que havia desviado a própria obra de Lotwil para fins malignos, e que Lotwil matara com as próprias mãos anos antes. Quando a cabeça de Argelmach foi trazida do {red:blackrock-depths}Abismo Rocha Negra{/red}, não era de carne. Era uma máquina feita à imagem de Argelmach, e Lotwil temeu que outra se erguesse para tomar seu lugar.]=],
		},
	},
	mentions = {
		{ text = "Estudo dos {link:elements}Elementos{/link}: Rocha" },
		{ text = "Estudo dos {link:elements}Elementos{/link}: Rocha" },
		{ text = "Estudo dos {link:elements}Elementos{/link}: Rocha" },
		{ text = "Cabeças Frias Prevalecem" },
		{ text = "Giro... o Quê?" },
		{ text = "Isso Vai Ser Difícil" },
		{ text = "Isso Vai Ser Difícil, a engrenagem entregue" },
		{ text = "Isso Vai Ser Difícil, o guardião libertado" },
		{
			text = [=[A Ascensão das Máquinas, o fragmento trazido de {link:kargath}Karrath{/link}]=],
		},
		{ text = "A Ascensão das Máquinas, a cabeça de Argelmach" },
	},
	bonds = {
		{ id = "lucien-tosselwrench", name = "Lucien Tosselwrench", note = "seu assistente" },
		{ id = "hierophant-theodora-mulvadania", name = "Hierofante Theodora Mulvadania", note = "busca seu parecer" },
		{ id = "golem-lord-argelmach", name = "Senhor dos Golens Argelmach", note = "seu velho inimigo" },
	},
})

