Translate("ptBR", "rigglefuzz", {
	title = "Rigglefuzz",
	subtitle = "Cozinheiro Goblin dos Ermos",
	found = "O acampamento no Vale das Presas",
	hint = "Encontre o goblin que assa asas de urubu no meio dos Ermos.",
	allegiance = "Goblins",
	sections = {
		{
			title = "Resumo",
			text = [=[Rigglefuzz é um goblin que vive no coração dos {link:badlands}Ermos{/link}, onde sobrevive sendo esperto. Mantém as feras longe com bombas de clarão, e se orgulha de suas asas de urubu assadas na brasa, cujo cheiro, diz ele, atrai os famintos a quilômetros de distância. Ele também guarda rancor. Os Shadowforge o levaram certa vez para a {link:angor-fortress}Fortaleza Angor{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Foi Rigglefuzz quem ensinou aos Shadowforge o segredo das pedras estranhas de {link:uldaman}Uldaman{/link}. Levaram-no à {link:angor-fortress}Fortaleza Angor{/link} para estudar dois tipos de pedra da câmara, e ele descobriu que, tratadas do jeito certo, eram fontes de poder estáveis e duradouras. Quando lhes contou, eles o puseram para fora e começaram a escavar em busca de mais.]=],
		},
		{
			title = "Feitos",
			text = [=[• Faz bombas de clarão com pérolas azuis moídas, trazidas dos recifes da {link:stranglethorn-vale}Selva do Espinhaço{/link}.
• Assa asas de urubu e divide a receita com quem o ajuda.
• Quer as pedras de poder de {link:uldaman}Uldaman{/link} para seus próprios aparelhos.]=],
		},
	},
	mentions = {
		{ text = "Asas de Urubu na Brasa" },
		{ text = "Mergulho por Pérolas" },
		{ text = "Receita de Bomba de Clarão" },
		{ text = "Pedras de Poder" },
	},
	bonds = {
		{ id = "martek-the-exiled", name = "Martek, o Exilado", note = "divide o acampamento com ele" },
	},
})

