Translate("ptBR", "warlord-goretooth", {
	title = "Senhor da Guerra Goretooth",
	subtitle = "Comandante da Força Expedicionária de Karrath",
	found = "Karrath",
	hint = [=[Fale com o senhor da guerra que comanda o exército da Horda em Karrath.]=],
	allegiance = "Horda · Força Expedicionária de Karrath",
	aliases = { "Goretooth" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Senhor da Guerra Goretooth comanda a Força Expedicionária de {link:kargath}Karrath{/link}, o exército que a {link:horde}Horda{/link} mantém nos {link:badlands}Ermos{/link} para combater o {link:blackrock-clan}clã Rocha Negra{/link} e os {link:dark-iron-dwarves}Ferro Negro{/link} da {link:blackrock-mountain}Montanha Rocha Negra{/link}. É um soldado duro, ocupado demais para visitantes e orgulhoso demais para mostrar medo. Fala por ordens. Seus avisos de procurado estão pendurados por toda Karrath, e cada um promete um tributo a quem cumprir sua sentença.]=],
		},
		{
			title = "Importância",
			text = [=[Goretooth lidera a campanha mais longa da {link:horde}Horda{/link} nos {link:eastern-kingdoms}Reinos do Leste{/link}. Sua força sofreu muito: o general {link:dark-iron-dwarves}Ferro Negro{/link} Angerforge massacrou sua 109ª divisão. Goretooth jurou que Angerforge pagará por isso.]=],
		},
		{
			title = "Feitos",
			text = [=[• Comanda a F.E.K. a partir de {link:kargath}Karrath{/link}, com seus oficiais {link:lexlort}Lexlort{/link}, {link:galamav-the-marksman}Galamav{/link}, {link:shadowmage-vivian-lagrave}Vivian Lagrave{/link} e {link:hierophant-theodora-mulvadania}Theodora Mulvadania{/link}.
• Afixa ordens para matar os soldados Anvilrage do General Angerforge no {red:blackrock-depths}Abismo Rocha Negra{/red}.
• Planeja a operação que levará o Carniceiro da {link:blackrock-mountain}Rocha Negra{/link} à justiça.
• Ordena a morte dos senhores do {red:blackrock-spire}Pico da Rocha Negra{/red}.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nada está escrito sobre o clã de Goretooth ou sobre seus feitos antes da F.E.K.]=],
		},
	},
	chapters = {
		{
			title = "Matar à Vista",
			hint = "Atenda aos avisos do senhor da guerra contra os Ferro Negro.",
			text = [=[Os avisos foram afixados nos muros de {link:kargath}Karrath{/link} em nome do senhor da guerra. Os homens de Angerforge eram assassinos implacáveis, responsáveis pela chacina da 109ª. Cada guarda, carcereiro e oficial Anvilrage do Abismo devia ser destruído. Goretooth prometeu tributos, e prometeu coisa pior a Angerforge.]=],
		},
		{
			title = "Morte a Angerforge",
			hint = [=[Conclua a operação do senhor da guerra contra o general Ferro Negro.]=],
			text = [=[A última operação era a que o senhor da guerra esperava. O General Angerforge, o Carniceiro da {link:blackrock-mountain}Rocha Negra{/link}, foi morto no Abismo. Goretooth chamou aquilo de justiça, enfim, e deu um medalhão da F.E.K. a quem a executou.]=],
		},
		{
			title = "A Ordem do Senhor da Guerra",
			hint = "Cumpra a ordem do senhor da guerra no Pico da Rocha Negra.",
			text = [=[Goretooth ordenou a morte de três senhores do Pico da {link:blackrock-mountain}Rocha Negra{/link}, e pediu quaisquer documentos encontrados entre suas coisas. Os documentos voltaram a ele. Quando os leu, sua pele verde empalideceu por um momento. Diziam que Rend Blackhand vivia, um chefe tido como morto havia muito tempo. Goretooth mandou a notícia a {link:eitrigg}Eitrigg{/link} e a {link:thrall}Thrall{/link}, em {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[MATAR À VISTA: {link:dark-iron-dwarves}Anões Ferro Negro{/link}]=],
		},
		{
			text = [=[MATAR À VISTA: Oficiais {link:dark-iron-dwarves}Ferro Negro{/link} de Alta Patente]=],
		},
		{ text = "Operação: Morte a Angerforge" },
		{ text = "A Ordem do Senhor da Guerra" },
		{ text = "A Sabedoria de {link:eitrigg}Eitrigg{/link}" },
	},
	bonds = {
		{ id = "lexlort", name = "Lexlort", note = "seu chefe de reconhecimento" },
		{ id = "galamav-the-marksman", name = "Galamav, o Atirador", note = "um de seus oficiais" },
		{ id = "eitrigg", name = "Eitrigg", note = "quem melhor conhece os Rocha Negra" },
		{ id = "thrall", name = "Thrall", note = "seu Chefe Guerreiro" },
	},
})

