Translate("ptBR", "neeka-bloodscar", {
	title = "Neeka Bloodscar",
	subtitle = "Batedora-chefe de Karrath",
	found = "Karrath",
	hint = "Fale com a batedora-chefe de Karrath.",
	allegiance = "Horda · Karrath",
	aliases = { "Neeka" },
	sections = {
		{
			title = "Resumo",
			text = [=[Neeka Bloodscar é a batedora-chefe de {link:kargath}Karrath{/link}. Os {link:badlands}Ermos{/link} ficam perto das terras da {link:alliance}Aliança{/link} em {link:loch-modan}Loch Modan{/link}, e a estrada entre Karrath e {link:stonard}Pedregal{/link} é longa e perigosa. Seus mensageiros nem sempre chegam. Ela julga os recém-chegados por sua capacidade de sobreviver ao calor e às feras dos Ermos.]=],
		},
		{
			title = "Importância",
			text = [=[Neeka mantém {link:kargath}Karrath{/link} em contato com o resto da {link:horde}Horda{/link} no leste. Seus relatórios dizem que a {link:alliance}Aliança{/link} tem seus próprios problemas, e que alguns de seus inimigos podem ser também os da Horda.]=],
		},
